// backend/scripts/applyDynamicBackendStep3B3A.js
//
// DUO — Paso 3B3A: hardening runtime dinámico SIN abrir todavía el catálogo público.
//
// Uso desde la raíz del backend:
//   node scripts/applyDynamicBackendStep3B3A.js --dry-run
//   node scripts/applyDynamicBackendStep3B3A.js --apply
//
// Seguridad:
// - valida hashes exactos de los archivos actuales de producción;
// - aborta antes de escribir si encuentra una versión distinta;
// - crea backup;
// - escritura atómica;
// - NO conecta a Mongo ni hace requests de red.

import fs from "fs";
import path from "path";
import crypto from "crypto";

const ROOT = process.cwd();
const APPLY = process.argv.includes("--apply");

const FILES = [
  {
    file: "src/routes/orders.js",
    beforeSha256: "b2837b2ee2171b4bb315398fbc9b7893ff3b349136e1b0786bdadde201fac1dd",
    afterSha256: "4bdf611ecbe07e1a41564ad4efeb52caf614821eee782bd95a96e6eb42a13672",
    afterB64: "",
  },
  {
    file: "src/routes/appointments.js",
    beforeSha256: "35cd7a0ccc648b64ea74f99746c58413f5dc5bfd4b8b0e08e91a819bb9d0ae81",
    afterSha256: "a9b6aaa3476f94f08f385e486f481f3fcdf7a0c0b2dc3f8299ebffbf6bad5554",
    afterB64: "",
  },
  {
    file: "src/services/serviceCatalogRuntime.js",
    beforeSha256: "9abba001837a83f807d7ce79bd80bb577c28b2216f4381e3317e04a6256b20d7",
    afterSha256: "fd30599217bf52c0e96982ffe49215b35b9604fe792772a611f08135999b12f6",
    afterB64: "",
  },
  {
    file: "src/services/subscriptions/subscriptionBootstrap.js",
    beforeSha256: "97b83ad3642bb4f474129a8fb1a8121b0af7e8340f0ff3ad2421fbeb56df6b36",
    afterSha256: "a04f6855020d49fb0d6bfefae7cf537d3cf91c8c7ee5657131b474f16f06d1d0",
    afterB64: "",
  },
  {
    file: "src/services/subscriptions/subscriptionCoveragePreview.js",
    beforeSha256: "8fe35a613222c6ed5f7c1ceb4616df682fe9747e67d6f9f66d8bdd624e344f3d",
    afterSha256: "e1ae84ad9a9bd3ac25344662f66320cc4c86852da0ef427231636860671ab69b",
    afterB64: "",
  }
];

const PUBLIC_GUARDS = [
  {
    file: "src/routes/services.js",
    marker: 'const RUNTIME_SERVICE_KEYS = new Set(["EP", "RA", "RF", "SYN"]);',
  },
  {
    file: "src/routes/pricing.js",
    marker: 'const RUNTIME_PRICING_KEYS = new Set(["EP", "RA", "RF", "SYN"]);',
  },
];

function sha256(text) {
  return crypto.createHash("sha256").update(text).digest("hex");
}

function abs(rel) {
  return path.join(ROOT, rel);
}

function read(rel) {
  const file = abs(rel);
  if (!fs.existsSync(file)) throw new Error(`No existe ${rel}`);
  return fs.readFileSync(file, "utf8");
}

function timestamp() {
  const d = new Date();
  const p = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
}

function atomicWrite(rel, content) {
  const target = abs(rel);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  const tmp = `${target}.step3b3a.tmp`;
  fs.writeFileSync(tmp, content, "utf8");
  fs.renameSync(tmp, target);
}

try {
  // 3B3A deliberadamente NO abre /services ni /pricing al público.
  for (const guard of PUBLIC_GUARDS) {
    const text = read(guard.file);
    if (!text.includes(guard.marker)) {
      throw new Error(
        `${guard.file} ya no conserva el guard público esperado. ` +
        "No se aplica 3B3A sobre un backend con el release gate cambiado."
      );
    }
  }

  const planned = [];

  for (const entry of FILES) {
    const current = read(entry.file);
    const currentHash = sha256(current);
    const target = Buffer.from(entry.afterB64, "base64").toString("utf8");

    if (sha256(target) !== entry.afterSha256) {
      throw new Error(`Payload interno inválido para ${entry.file}.`);
    }

    if (currentHash === entry.afterSha256) {
      planned.push({
        ...entry,
        status: "ALREADY_APPLIED",
        changed: false,
        current,
        target,
        currentHash,
      });
      continue;
    }

    if (currentHash !== entry.beforeSha256) {
      throw new Error(
        `${entry.file} no coincide con la versión exacta esperada. ` +
        `actual=${currentHash.slice(0,16)} esperado=${entry.beforeSha256.slice(0,16)}. ` +
        "No se escribió ningún archivo."
      );
    }

    planned.push({
      ...entry,
      status: "READY",
      changed: true,
      current,
      target,
      currentHash,
    });
  }

  const result = {
    ok: true,
    mode: APPLY ? "APPLY" : "DRY_RUN",
    root: ROOT,
    publicUnlockStillClosed: true,
    files: planned.map((item) => ({
      file: item.file,
      status: item.status,
      changed: item.changed,
      beforeHash: item.currentHash.slice(0, 16),
      afterHash: item.afterSha256.slice(0, 16),
    })),
    filesWritten: 0,
  };

  const changing = planned.filter((item) => item.changed);

  if (APPLY && changing.length) {
    const backupDir = path.join(
      ROOT,
      "backups",
      `services-step3b3a-${timestamp()}`
    );

    for (const item of changing) {
      const backup = path.join(backupDir, item.file);
      fs.mkdirSync(path.dirname(backup), { recursive: true });
      fs.writeFileSync(backup, item.current, "utf8");
    }

    for (const item of changing) {
      atomicWrite(item.file, item.target);
    }

    for (const item of changing) {
      const written = read(item.file);
      const writtenHash = sha256(written);
      if (writtenHash !== item.afterSha256) {
        throw new Error(
          `Hash inesperado después de escribir ${item.file}: ` +
          `${writtenHash.slice(0,16)} != ${item.afterSha256.slice(0,16)}`
        );
      }
    }

    result.filesWritten = changing.length;
    result.backupDir = path.relative(ROOT, backupDir);
  }

  console.log(JSON.stringify(result, null, 2));
} catch (error) {
  console.error(JSON.stringify({
    ok: false,
    mode: APPLY ? "APPLY" : "DRY_RUN",
    error: error?.message || String(error),
    filesWritten: 0,
  }, null, 2));
  process.exitCode = 1;
}
